import pty,os,fcntl,termios,struct
def run(cols, args):
    pid,fd=pty.fork()
    if pid==0:
        os.execv('/workspace/executable',['pier']+args)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH',24,cols,0,0))
    out=b''
    try:
        while True:
            d=os.read(fd,4096)
            if not d: break
            out+=d
    except OSError: pass
    os.waitpid(pid,0)
    return out.decode()
for c in (40,60,200):
    print('=== cols',c)
    print(run(c,['add','-h']))
